#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main() {
    int startYear = 2023;
    int endYear = 2023;
    int startMonth = 3;
    int startDay = 11;
    int endMonth = 7;
    int endDay = 1;

    int days = 0;

    for(int year = startYear; year <= endYear; year++) {
        for(int month = startMonth; month <= endMonth; month++) {
            if(month < endMonth || year == endYear && month == endMonth) {
                int day = 1;
                while(day <= endDay) {
                    printf("%04d/%02d/%02d\n", year, month, day);
                    day++;
                }
            }
        }
    }

    printf("日数差: %d\n", days);

    return 0;
}

