javascript
正解数は0
不正解数は0
問題データ＝[
　　{"q":"リンゴは英語で？", "a":"apple"},
　　{"q":"ミカンは英語で？", "a":"orange"},
　　{"q":"バナナは英語で？", "a":"banana"}
]
問題データを反復
　　問題文＝対象["q"]
　　答え＝対象["a"]
　　「{問題文}」と尋ねて、入力文に代入。
　　もし、入力文＝答えならば
　　　　「正解！」と表示。
　　　　正解数＝正解数+1
　　違えば
　　　　「不正解（答えは{答え}）」と表示。
　　　　不正解数＝不正解数+1
　　ここまで。
「正解:{正解数} / 不正解:{不正解数}」

for (var i = 0; i < 問題データ.length; i++) {
    var question = 問題データ[i]["q"];
    var answer = 問題データ[i]["a"];
    var response = prompt(question);
    if (response === answer) {
        console.log("正解!");
        global正解数++;
    } else {
        console.log(`不正解（答えは${answer}）`);
        global不正解数++;
    }
}
console.log(`正解:${global正解数} / 不正解:${global不正解数}`);

